1	import type { Metadata } from "next";
2	import { Geist, Geist_Mono } from "next/font/google";
3	import "./globals.css";
4	
5	// Brand typeface, loaded once site-wide and self-hosted by next/font (no CDN at
6	// runtime). Exposed as CSS variables that globals.css maps onto Tailwind's
7	// --font-sans / --font-mono, so every page + the dashboard share one typeface
8	// instead of the browser default. Geist Mono backs the terminal/code surfaces.
9	const geistSans = Geist({ subsets: ["latin"], variable: "--font-geist-sans", display: "swap" });
10	const geistMono = Geist_Mono({ subsets: ["latin"], variable: "--font-geist-mono", display: "swap" });
11	import { Analytics } from "@/components/marketing/Analytics";
12	import { TrackingProvider } from "@/components/marketing/TrackingProvider";
13	import MetaPixelTracker from "@/components/marketing/MetaPixelTracker";
14	import { OrganizationJsonLd } from "@/components/marketing/StructuredData";
15	import CookieConsent from "@/components/marketing/CookieConsent";
16	import LiveChat from "@/components/marketing/LiveChat";
17	import ChatWidget from "@/components/ChatWidget";
18	import { SandboxBanner } from "@/components/SandboxBanner";
19	
20	const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
21	const DESCRIPTION =
22	  "High-performance NVMe VPS hosting with instant deployment — control panels, game servers, VPNs, and domains. Deploy a server in seconds with full root access and a dedicated IP option.";
23	
24	/**
25	 * Root metadata. A function, not a constant, because the platform name comes from
26	 * Settings → General (`brand_name`) — every string below used to hardcode "Nxeon", so
27	 * renaming the platform in the admin panel changed the browser tab, the per-page title
28	 * template, the Open Graph site name and the author/creator/publisher meta tags on exactly
29	 * nothing. Next.js only awaits a DB read here if the export is `generateMetadata`.
30	 *
31	 * Still hardcoded and out of scope for this pass: the schema.org JSON-LD in
32	 * components/marketing/StructuredData.tsx (Organization, Product, BlogPosting).
33	 *
34	 * Failure of the settings read is non-fatal on purpose and mirrors the `livechat_snippet`
35	 * read below: if Postgres is unreachable, the correct outcome is a page that renders with
36	 * the default title, not a 500 on the root layout that takes the whole site (including
37	 * /status) down with it.
38	 */
39	export async function generateMetadata(): Promise<Metadata> {
40	  // Only used when @/lib/settings cannot even be loaded. Kept a local literal rather
41	  // than a static SETTINGS_DEFAULTS import so the root layout still has no top-level
42	  // dependency on Prisma — the same reason the livechat read below is a dynamic import.
43	  let brand = "Nxeon";
44	  let fbDomainVerify = "";
45	  try {
46	    const { getSetting, SETTINGS_DEFAULTS } = await import("@/lib/settings");
47	    brand = (await getSetting("brand_name")).trim() || SETTINGS_DEFAULTS.brand_name;
48	    fbDomainVerify = (await getSetting("meta_domain_verification")).trim();
49	  } catch {
50	    /* settings unavailable — fall back to the built-in brand name */
51	  }
52	  return {
53	    metadataBase: new URL(APP_URL),
54	    // Meta Business domain verification — emits <meta name="facebook-domain-verification">
55	    // only when an operator has set the token in admin → Marketing → Tracking.
56	    ...(fbDomainVerify
57	      ? { verification: { other: { "facebook-domain-verification": fbDomainVerify } } }
58	      : {}),
59	    title: {
60	      default: `${brand} — Cloud VPS Hosting, Game Servers & Domains`,
61	      template: `%s — ${brand}`,
62	    },
63	    description: DESCRIPTION,
64	    applicationName: brand,
65	    keywords: [
66	      "VPS hosting",
67	      "cloud VPS",
68	      "game server hosting",
69	      "Minecraft server hosting",
70	      "NVMe VPS",
71	      "affordable VPS",
72	      "domain registration",
73	      "dedicated IP",
74	      "Singapore VPS",
75	      "cPanel hosting",
76	    ],
77	    authors: [{ name: brand }],
78	    creator: brand,
79	    publisher: brand,
80	    alternates: { canonical: "/" },
81	    openGraph: {
82	      type: "website",
83	      siteName: brand,
84	      url: APP_URL,
85	      locale: "en_US",
86	    },
87	    twitter: {
88	      card: "summary_large_image",
89	    },
90	    robots: {
91	      index: true,
92	      follow: true,
93	      googleBot: {
94	        index: true,
95	        follow: true,
96	        "max-image-preview": "large",
97	        "max-snippet": -1,
98	        "max-video-preview": -1,
99	      },
100	    },
101	    icons: {
102	      icon: [
103	        { url: "/favicon.ico", sizes: "any" },
104	        { url: "/icon-192.png", sizes: "192x192", type: "image/png" },
105	        { url: "/icon-512.png", sizes: "512x512", type: "image/png" },
106	      ],
107	      shortcut: "/favicon.ico",
108	      apple: "/apple-touch-icon.png",
109	    },
110	    manifest: "/manifest.webmanifest",
111	  };
112	}
113	
114	export default async function RootLayout({ children }: { children: React.ReactNode }) {
115	  // Admin-configured live-chat snippet (trusted input — only staff can set it).
116	  let chatSnippet = "";
117	  try {
118	    const { getSetting } = await import("@/lib/settings");
119	    chatSnippet = (await getSetting("livechat_snippet", "")) ?? "";
120	  } catch {
121	    /* settings unavailable — chat stays off */
122	  }
123	
124	  // Signed-in viewer (if any) so the chat widget prefills name/email and doesn't
125	  // re-ask; anonymous visitors are required to provide them. Best-effort.
126	  let chatViewer: { name: string | null; email: string | null } | null = null;
127	  try {
128	    const { currentUser } = await import("@/lib/auth");
129	    const u = await currentUser();
130	    if (u) chatViewer = { name: u.name ?? null, email: u.email ?? null };
131	  } catch {
132	    /* not signed in / auth unavailable — widget will ask for details */
133	  }
134	  return (
135	    <html lang="en" className={`${geistSans.variable} ${geistMono.variable}`}>
136	      <body>
137	        <SandboxBanner />
138	        {children}
139	        <CookieConsent />
140	        <LiveChat snippet={chatSnippet} />
141	        <ChatWidget viewer={chatViewer} />
142	        <OrganizationJsonLd />
143	        <Analytics />
144	        <TrackingProvider />
145	        <MetaPixelTracker />
146	      </body>
147	    </html>
148	  );
149	}
