23	export const metadata: Metadata = {
24	  title: "Pricing",
25	  description:
26	    "One place to compare every Nxeon product — Cloud VPS, game servers, shared web hosting, business email and domains. Live catalogue prices, monthly billing, no lock-in.",
27	  alternates: { canonical: "/pricing" },
