34	function gb(mb: number): string {
35	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
36	}
37	/** Base MONTHLY price for a plan. VPS/Hosting store a monthly `priceCents`; Email &
38	 *  Game store it per `termMonths`, so normalise to a per-month figure. All display
39	 *  math downstream runs THIS through termPriceCents — the formula checkout charges. */
40	function monthlyOf(p: { priceCents: number; termMonths?: number }): number {
41	  const t = p.termMonths ?? 1;
42	  return t > 1 ? Math.round(p.priceCents / t) : p.priceCents;
43	}
