59	export default async function PricingPage() {
60	  // Every product line's prices, read LIVE from the catalogue. Nothing below is
61	  // hard-coded; a catalogue edit or deactivation propagates here automatically.
62	  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
63	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
64	    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
65	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
66	    db.gamePlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
67	  ]);
68	
69	  // The REAL, live annual discount + add-on prices (admin settings) — never
70	  // marketing constants. These are the SAME figures lib/order.ts bills, so the
71	  // add-on builder's "your build" total is displayed === charged.
72	  const [annualPct, backupPlusCents, extraDiskGbCents] = await Promise.all([
73	    annualDiscountPct(),
74	    backupPlusMonthlyCents(),
75	    extraDiskPerGbCents(),
76	  ]);
77	
78	  // Promo copy from the single source of truth — surfaced ONLY where the owner
79	  // scoped it (shared web hosting) via firstMonthFreeAppliesTo("HOSTING"). It is
80	  // passed as a nullable label so the badge cannot render on any other product.
81	  const hostingPromoLabel = firstMonthFreeAppliesTo("HOSTING") ? currentPromo(new Date()).label : null;
82	
83	  // ── VPS: 4 tiers. Middle = "Most popular" (violet), last = "Best value" (cyan). ──
84	  const vps: ExplorerPlan[] = vpsPlans.map((p, i) => ({
85	    id: p.id,
86	    name: p.name,
87	    monthlyCents: monthlyOf(p),
88	    // Optional LOW intro price → the card shows "$intro first term, then $regular/mo".
89	    // Null (no intro set) leaves the card at the plain regular price, unchanged.
90	    introMonthlyCents: planIntroMonthlyCents(p),
91	    badge:
92	      vpsPlans.length >= 3 && i === Math.floor((vpsPlans.length - 1) / 2)
93	        ? "popular"
94	        : vpsPlans.length >= 3 && i === vpsPlans.length - 1
95	          ? "best"
96	          : undefined,
97	    specs: [
98	      { label: "CPU", value: `${p.cpuCores} vCPU` },
99	      { label: "RAM", value: gb(p.ramMB) },
100	      { label: "Storage", value: `${p.diskGB} GB NVMe` },
101	      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
102	    ],
103	    href: DEPLOY_HREF,
104	  }));
105	
106	  // ── Hosting: featured tier gets the violet "Most popular" badge. ──
107	  const hosting: ExplorerPlan[] = hostingPlans.map((p, i) => ({
108	    id: p.id,
109	    name: p.name,
110	    monthlyCents: monthlyOf(p),
111	    badge: p.featured || (hostingPlans.length >= 3 && i === Math.floor((hostingPlans.length - 1) / 2)) ? "popular" : undefined,
112	    specs: [
113	      { label: "Disk", value: `${p.diskGB} GB` },
114	      { label: "Websites", value: String(p.maxSites) },
115	      { label: "Databases", value: String(p.maxDatabases) },
116	      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
117	      { label: "Mailboxes", value: p.mailboxes < 0 ? "Unlimited" : String(p.mailboxes) },
118	    ],
119	    href: DEPLOY_HREF,
120	  }));
121	
122	  // ── Business Email: mailbox plans. ──
123	  const email: ExplorerPlan[] = emailPlans.map((p, i) => ({
124	    id: p.id,
125	    name: p.name,
126	    monthlyCents: monthlyOf(p),
127	    badge: emailPlans.length >= 3 && i === Math.floor((emailPlans.length - 1) / 2) ? "popular" : undefined,
128	    specs: [
129	      { label: "Mailboxes", value: `${p.mailboxes} mailbox${p.mailboxes === 1 ? "" : "es"}` },
130	      { label: "Storage", value: `${p.storageGB} GB / mailbox` },
131	      { label: "Filtering", value: "Spam & virus" },
132	      { label: "Sync", value: "Calendars & contacts" },
133	    ],
134	    href: DEPLOY_HREF,
135	  }));
136	
137	  // ── Game servers: grouped by family, canonical order, families with real plans only. ──
138	  const byGame = new Map<string, typeof gamePlans>();
139	  for (const g of gamePlans) {
140	    if (!byGame.has(g.gameFamily)) byGame.set(g.gameFamily, []);
141	    byGame.get(g.gameFamily)!.push(g);
142	  }
143	  const games: ExplorerGameFamily[] = GAME_FAMILIES.filter((f) => (byGame.get(f)?.length ?? 0) > 0).map((fam) => {
144	    const tiers = (byGame.get(fam) ?? []).slice().sort((a, b) => a.priceCents - b.priceCents);
145	    return {
146	      id: fam,
147	      name: GAME_DISPLAY[fam].name,
148	      plans: tiers.map((t) => ({
149	        id: t.id,
150	        name: t.name,
151	        monthlyCents: monthlyOf(t),
152	        badge: t.featured ? ("popular" as const) : undefined,
153	        specs: [
154	          { label: "RAM", value: gb(t.ramMB) },
155	          { label: "CPU", value: `${t.cpuCores} vCPU` },
156	          { label: "Storage", value: `${t.diskGB} GB` },
157	          ...(t.slots != null ? [{ label: "Slots", value: `${t.slots} slots` }] : []),
158	        ],
159	        href: DEPLOY_HREF,
160	      })),
161	    };
162	  });
163	
164	  const tlds = POPULAR_TLDS.map((t) => ({ tld: t.tld, fromCents: t.fromCents }));
165	
166	  return (
167	    <>
168	      {vpsPlans.length > 0 && <ProductJsonLd plans={vpsPlans} />}
169	      <FaqJsonLd items={FAQ} />
170	
171	      {/* No `overflow-hidden` here: it was slicing the plan-card glows and the
172	          per-panel/hero auras with a hard rectangular edge at the layout sides.
173	          Box-shadow glows never create a scrollbar, and the ambient layer is
174	          `absolute inset-0` (self-contained), so nothing here needs clipping —
175	          the one element that could bleed horizontally (the panel aura) is
176	          contained to `inset-x-0` in PricingExplorer instead. */}
177	      <div className="relative min-h-screen">
178	        {/* Ambient dot-field + violet/blue aura for depth (the v5 signature). */}
179	        <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
180	          <AmbientField />
181	          <div className="absolute inset-0 hero-aura opacity-80" />
182	        </div>
183	
184	        <div className="relative z-10">
185	          <PricingExplorer
186	            annualPct={annualPct}
187	            vps={vps}
188	            hosting={hosting}
189	            email={email}
190	            games={games}
191	            tlds={tlds}
192	            hostingPromoLabel={hostingPromoLabel}
193	            included={INCLUDED}
194	            domainsHref={DOMAINS_HREF}
195	            backupPlusCents={backupPlusCents}
196	            extraDiskPerGbCents={extraDiskGbCents}
197	            reviewBadges={<ReviewBadges />}
198	          />
199	        </div>
200	      </div>
201	    </>
202	  );
203	}
